create extension if not exists pgcrypto;
create table public.organizations(id uuid primary key default gen_random_uuid(),name text not null,created_at timestamptz not null default now());
create table public.memberships(organization_id uuid references public.organizations on delete cascade,user_id uuid references auth.users on delete cascade,role text not null default 'owner' check(role in ('owner','member')),primary key(organization_id,user_id));
create function public.is_member(oid uuid) returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from memberships where organization_id=oid and user_id=auth.uid())$$;
create function public.create_organization(org_name text) returns uuid language plpgsql security definer set search_path=public as $$declare oid uuid; begin if auth.uid() is null then raise exception 'Authentication required'; end if; if length(org_name) not between 1 and 120 then raise exception 'Invalid name'; end if; if exists(select 1 from memberships where user_id=auth.uid()) then raise exception 'Already provisioned'; end if; insert into organizations(name) values(org_name) returning id into oid; insert into memberships values(oid,auth.uid(),'owner'); return oid; end$$;
revoke all on function public.create_organization(text) from public;
grant execute on function public.create_organization(text) to authenticated;
create table public.jurisdictions(id text primary key,name text not null,department_url text not null,portal_url text,verified_at date);
insert into public.jurisdictions values('san-jose','City of San José','https://www.sanjoseca.gov/your-government/departments-offices/planning-building-code-enforcement/building-division','https://sjpermits.org',null),('santa-clara','Santa Clara County (unincorporated)','https://plandev.santaclaracounty.gov/','https://aca-prod.accela.com/SCCGOV/',null);
create table public.projects(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations on delete cascade,name text not null check(length(name) between 2 and 120),data jsonb not null default '{}',created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(id,organization_id));
create table public.properties(id uuid primary key default gen_random_uuid(),project_id uuid not null unique,organization_id uuid not null,address text not null,city text,state text,zip text,jurisdiction_id text references public.jurisdictions,confirmation_status text not null default 'unconfirmed' check(confirmation_status in ('unconfirmed','manual','authoritative')),foreign key(project_id,organization_id) references public.projects(id,organization_id) on delete cascade);
create table public.project_categories(project_id uuid not null,organization_id uuid not null,category text not null,primary key(project_id,category),foreign key(project_id,organization_id) references public.projects(id,organization_id) on delete cascade);
create table public.requirements(id uuid primary key default gen_random_uuid(),jurisdiction_id text not null references public.jurisdictions,category text not null,code text unique not null);
create table public.requirement_versions(id uuid primary key default gen_random_uuid(),requirement_id uuid not null references public.requirements,version integer not null,title text not null,description text not null,conditions jsonb not null,required_support text not null,source_url text not null check(source_url like 'https://%'),effective_date date,verified_at date,verification_status text not null check(verification_status in ('verified','unverified','retired')),limitations text not null,unique(requirement_id,version),check(verification_status<>'verified' or verified_at is not null));
create table public.checklist_results(id uuid primary key default gen_random_uuid(),project_id uuid not null,organization_id uuid not null,requirement_version_id uuid references public.requirement_versions,status text not null check(status in ('Complete','Missing','Needs clarification','Needs professional review','Not applicable','Not verified or unsupported')),notes text,foreign key(project_id,organization_id) references public.projects(id,organization_id) on delete cascade);
create table public.documents(id uuid primary key default gen_random_uuid(),project_id uuid not null,organization_id uuid not null,path text not null unique,name text not null,mime_type text not null check(mime_type in ('application/pdf','image/jpeg','image/png')),size bigint not null check(size>0 and size<=20971520),created_at timestamptz not null default now(),foreign key(project_id,organization_id) references public.projects(id,organization_id) on delete cascade,check(path=organization_id::text||'/'||project_id::text||'/'||id::text));
create table public.document_analysis(id uuid primary key default gen_random_uuid(),document_id uuid not null references public.documents on delete cascade,organization_id uuid not null references public.organizations,facts jsonb not null,model text not null,created_at timestamptz not null default now());
create table public.readiness_reports(id uuid primary key default gen_random_uuid(),project_id uuid not null,organization_id uuid not null,snapshot jsonb not null,created_at timestamptz not null default now(),foreign key(project_id,organization_id) references public.projects(id,organization_id) on delete cascade);
create table public.activity_records(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations,user_id uuid references auth.users,action text not null,entity_id uuid,created_at timestamptz not null default now());
alter table public.organizations enable row level security;
create policy org_read on public.organizations for select to authenticated using(public.is_member(id));
alter table public.memberships enable row level security;
create policy membership_read on public.memberships for select to authenticated using(public.is_member(organization_id));
do $$declare t text;begin foreach t in array array['projects','properties','project_categories','checklist_results','documents','readiness_reports'] loop execute format('alter table public.%I enable row level security',t);execute format('create policy organization_access on public.%I for all to authenticated using(public.is_member(organization_id)) with check(public.is_member(organization_id))',t);end loop;end$$;
alter table public.document_analysis enable row level security;
create policy analysis_read on public.document_analysis for select to authenticated using(public.is_member(organization_id));
create policy analysis_insert on public.document_analysis for insert to authenticated with check(public.is_member(organization_id) and exists(select 1 from public.documents d where d.id=document_id and d.organization_id=document_analysis.organization_id));
alter table public.activity_records enable row level security;
create policy activity_read on public.activity_records for select to authenticated using(public.is_member(organization_id));
do $$declare t text;begin foreach t in array array['jurisdictions','requirements','requirement_versions'] loop execute format('alter table public.%I enable row level security',t);execute format('create policy authenticated_read on public.%I for select to authenticated using(true)',t);end loop;end$$;
create function public.audit_project() returns trigger language plpgsql security definer set search_path=public as $$begin insert into activity_records(organization_id,user_id,action,entity_id) values(coalesce(new.organization_id,old.organization_id),auth.uid(),TG_OP,coalesce(new.id,old.id));if TG_OP='DELETE' then return old;end if;new.updated_at=now();return new;end$$;
create trigger project_audit before insert or update or delete on public.projects for each row execute function public.audit_project();
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('project-documents','project-documents',false,20971520,array['application/pdf','image/jpeg','image/png']);
create policy private_docs_read on storage.objects for select to authenticated using(bucket_id='project-documents' and exists(select 1 from public.projects p where p.organization_id::text=(storage.foldername(storage.objects.name))[1] and p.id::text=(storage.foldername(storage.objects.name))[2] and public.is_member(p.organization_id)));
create policy private_docs_insert on storage.objects for insert to authenticated with check(bucket_id='project-documents' and exists(select 1 from public.projects p where p.organization_id::text=(storage.foldername(storage.objects.name))[1] and p.id::text=(storage.foldername(storage.objects.name))[2] and public.is_member(p.organization_id)));
create policy private_docs_delete on storage.objects for delete to authenticated using(bucket_id='project-documents' and exists(select 1 from public.projects p where p.organization_id::text=(storage.foldername(storage.objects.name))[1] and p.id::text=(storage.foldername(storage.objects.name))[2] and public.is_member(p.organization_id)));
-- Persist the intake, normalized property and category data in one transaction.
create function public.save_project(project_data jsonb,oid uuid) returns uuid language plpgsql security invoker set search_path=public as $$declare pid uuid;begin
if not public.is_member(oid) then raise exception 'Organization access denied';end if;
pid=(project_data->>'id')::uuid;
if exists(select 1 from projects where id=pid and organization_id<>oid) then raise exception 'Project access denied';end if;
insert into projects(id,organization_id,name,data) values(pid,oid,project_data->>'name',project_data) on conflict(id) do update set name=excluded.name,data=excluded.data;
insert into properties(project_id,organization_id,address,city,state,zip,jurisdiction_id,confirmation_status) values(pid,oid,project_data->>'address',project_data->>'city',project_data->>'state',project_data->>'zip',case when project_data->>'jurisdiction' in ('san-jose','santa-clara') then project_data->>'jurisdiction' else null end,case when (project_data->>'confirmed')::boolean then 'manual' else 'unconfirmed' end) on conflict(project_id) do update set address=excluded.address,city=excluded.city,state=excluded.state,zip=excluded.zip,jurisdiction_id=excluded.jurisdiction_id,confirmation_status=excluded.confirmation_status;
delete from project_categories where project_id=pid;
insert into project_categories(project_id,organization_id,category) select pid,oid,jsonb_array_elements_text(project_data->'categories');
return pid;end$$;
revoke all on function public.save_project(jsonb,uuid) from public;
grant execute on function public.save_project(jsonb,uuid) to authenticated;
create policy org_owner_update on public.organizations for update to authenticated using(exists(select 1 from public.memberships m where m.organization_id=id and m.user_id=auth.uid() and m.role='owner')) with check(exists(select 1 from public.memberships m where m.organization_id=id and m.user_id=auth.uid() and m.role='owner'));
